  // 成分間・穴への出入りは面積ゼロのブリッジで結ぶ（一筆書き）。
  //   w = −1 (int T) / 0 (それ以外)
  // T 内で裏面が最上層に来ることは補題 3.2 から従う。
  // T 外は w = 0 のため層数が偶数となり、最上層の向きは確定しない。
  const plan=planBridges(Ts,holes);
  const {nodes,bridges}=plan;
